==> dto/create-booking.dto.ts <==
import { IsEmail, IsISO8601, IsString, IsUUID, Length } from 'class-validator';
import { BOOKING_TITLE_MAX_LENGTH } from '../contract.constants';

export class CreateBookingDto {
  @IsUUID()
  roomId: string;

  @IsString()
  @Length(1, BOOKING_TITLE_MAX_LENGTH)
  title: string;

  @IsEmail()
  organizerEmail: string;

  @IsISO8601({ strict: true })
  startsAt: string;

  @IsISO8601({ strict: true })
  endsAt: string;
}

==> dto/list-bookings-query.dto.ts <==
import { IsOptional, IsUUID } from 'class-validator';
import { PageQueryDto } from './page-query.dto';

export class ListBookingsQueryDto extends PageQueryDto {
  @IsOptional()
  @IsUUID()
  roomId?: string;
}

==> dto/page-query.dto.ts <==
import { Type } from 'class-transformer';
import { IsInt, Max, Min } from 'class-validator';
import { DEFAULT_PAGE_SIZE, MAX_PAGE_SIZE } from '../contract.constants';

export class PageQueryDto {
  @Type(() => Number)
  @IsInt()
  @Min(1)
  page = 1;

  @Type(() => Number)
  @IsInt()
  @Min(1)
  @Max(MAX_PAGE_SIZE)
  limit = DEFAULT_PAGE_SIZE;
}

